<script setup>
import {computed,ref,onMounted} from 'vue';
import ReviewIcon from './ReviewIcon.vue';
const dialog=ref(null);
onMounted(()=>dialog.value?.focus());
const props=defineProps({result:Object,filename:String,templateName:String});
defineEmits(['close','locate']);
const fallback=computed(()=>{
 const fields=(props.result.values||[]).map(v=>({...v,status:!v.reason?'pass':v.reason==='该字段配置为转人工'?'manual':'issue'}));
 const counts={total:fields.length,pass:0,manual:0,issue:0,not_checked:0,differences:props.result.differences?.length||0};
 fields.forEach(v=>counts[v.status]++);
 return {fields,counts,differences:props.result.differences||[],limitations:props.result.result==='UNDETERMINED'?[props.result.reason]:[],status:counts.issue||counts.differences?'needs_changes':props.result.result==='UNDETERMINED'?'incomplete':counts.manual?'needs_review':'pass'};
});
const report=computed(()=>props.result.report||fallback.value);
const pending=computed(()=>report.value.fields.filter(v=>v.status!=='pass'));
const tab=ref(pending.value.length?'pending':report.value.differences.length?'differences':'fields');
const rows=computed(()=>tab.value==='pending'?pending.value:report.value.fields);
const labels={pass:'符合规则',manual:'需人工审核',issue:'需要修改',not_checked:'未能检查'};
const titles={pass:'已检查内容符合模板规则',needs_changes:'发现需要修改的内容',incomplete:'检查未完成，部分内容需人工核对',needs_review:'填写内容需要人工审核'};
const advice=computed(()=>report.value.status==='pass'?'已检查的文字和填写规则符合要求。你可以继续核验模板或更换合同再次验证。':report.value.status==='needs_changes'?'先查看下方的填写问题和条款变化，修改合同或调整模板标记后重新验证。':report.value.status==='incomplete'?'下方列出了已检查的结果。请在“检查范围”中查看未能检查的原因，并人工核对这些内容。':'这些区域设置为人工审核，内容仍需人工确认；这不代表填写错误。');
function explanation(row){return row.status==='pass'?'符合当前字段规则':row.status==='manual'?'该区域设置为人工审核，需由审核人员确认填写内容。':row.reason;}
</script>
<template>
 <div class="validation-overlay" @click.self="$emit('close')" @keydown.esc="$emit('close')">
  <section ref="dialog" class="validation-dialog" role="dialog" aria-modal="true" aria-labelledby="validation-title" tabindex="-1">
   <header class="validation-header"><div><h2 id="validation-title">合同验证结果</h2><p :title="filename+' · '+templateName">验证文件：{{filename||'已上传合同'}} <span>对照模板：{{templateName}}</span></p></div><button class="validation-close" aria-label="关闭验证结果" @click="$emit('close')">×</button></header>
   <div class="validation-summary" :class="report.status"><span class="validation-summary-icon"><ReviewIcon :name="report.status==='pass'?'check':'info'"/></span><div><h3>{{titles[report.status]}}</h3><p>{{advice}}</p><p v-if="report.limitations.length" class="validation-limit">未完成原因：{{report.limitations[0]}} <button @click="tab='scope'">查看检查范围 →</button></p></div></div>
   <div class="validation-counts"><div><strong>{{report.counts.pass}}</strong><span>符合规则</span></div><div><strong>{{report.counts.issue}}</strong><span>填写问题</span></div><div><strong>{{report.counts.manual}}</strong><span>需人工审核</span></div><div><strong>{{report.counts.differences}}</strong><span>条款变化</span></div><div><strong>{{report.counts.not_checked}}</strong><span>未能检查的字段</span></div></div>
   <nav class="validation-tabs" aria-label="验证结果分类"><button :class="{active:tab==='pending'}" @click="tab='pending'">待处理 <b>{{pending.length}}</b></button><button :class="{active:tab==='fields'}" @click="tab='fields'">全部填写内容 <b>{{report.counts.total}}</b></button><button :class="{active:tab==='differences'}" @click="tab='differences'">条款变化 <b>{{report.counts.differences}}</b></button><button :class="{active:tab==='scope'}" @click="tab='scope'">检查范围 <i v-if="report.limitations.length"></i></button></nav>
   <div class="validation-body">
    <template v-if="tab==='fields'||tab==='pending'">
     <p class="validation-intro">{{tab==='pending'?'优先处理以下区域。“需人工审核”来自模板设置，不等于填写错误。':'以下是从上传合同中读取的填写内容，以及按当前模板规则得出的检查结果。'}}</p>
     <div v-if="!rows.length" class="validation-empty"><ReviewIcon name="check"/><strong>没有待处理的填写项</strong><p>还可以查看“条款变化”和“检查范围”。</p></div>
     <div v-else class="validation-table-wrap"><table class="validation-table"><thead><tr><th>填写区域</th><th>合同中的内容</th><th>检查结果与处理建议</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{row.name}}</strong></td><td><span :class="{'validation-value-empty':!row.value?.trim()}">{{row.value===null?'（未能定位）':row.value?.trim()||'（空白）'}}</span><p v-if="row.unchanged" class="validation-unchanged">与模板原文相同，请核对是否已填写，或是否误选了字段名称。</p></td><td><span class="validation-badge" :class="row.status">{{labels[row.status]}}</span><p>{{explanation(row)}}</p></td><td><button class="validation-locate" @click="$emit('locate',row.id)">查看标记 <ReviewIcon name="arrow"/></button></td></tr></tbody></table></div>
    </template>
    <template v-else-if="tab==='differences'"><p class="validation-intro">填写区域以外的文字应与模板一致。请核对以下修改是否允许。</p><div v-if="!report.differences.length" class="validation-empty"><ReviewIcon name="check"/><strong>已检查部分未发现固定条款变化</strong><p v-if="report.limitations.length">存在未能完整检查的内容，请同时查看“检查范围”。</p></div><article v-for="(item,i) in report.differences" :key="i" class="validation-difference"><h4>变化 {{i+1}} · {{item.reason}}</h4><div><section><span>模板原文</span><p>{{item.original}}</p></section><section><span>上传合同</span><p>{{item.current}}</p></section></div></article></template>
    <template v-else><section class="validation-scope"><h4>这次验证检查了什么</h4><p>把上传的合同与当前模板草稿对比，检查固定文字是否改变，以及已标记区域的必填、长度、类型和取值规则。</p><h4>哪些内容需要另外核对</h4><ul v-if="report.limitations.length"><li v-for="(item,i) in report.limitations" :key="i">{{item}}</li></ul><p v-else>未报告影响文字检查的文档结构问题。</p><p>文档格式、合并单元格、图片及嵌入对象不在完整检查范围内。请打开原文件人工核对。</p><h4>接下来怎么做</h4><p>修正“待处理”中的填写问题，核对“条款变化”，并人工确认未能检查的部分。若字段位置选错，可点击“查看标记”返回调整后重新验证。</p><div class="validation-scope-note">这次操作仅验证模板规则，不会提交审批、自动免审或发布模板。</div></section></template>
   </div>
   <footer class="validation-footer"><span>验证不会修改模板或上传合同</span><button class="button primary" @click="$emit('close')">返回模板核验</button></footer>
  </section>
 </div>
</template>
<style scoped>
