umns:repeat(5,1fr);margin:0 24px 17px;border:1px solid #e5eaf1;border-radius:8px;padding:13px 0;flex-shrink:0}.validation-counts>div{display:flex;gap:8px;align-items:baseline;justify-content:center;border-right:1px solid #e8edf3}.validation-counts>div:last-child{border:0}.validation-counts strong{font-size:23px;font-weight:600;font-variant-numeric:tabular-nums;color:#475b7a}.validation-counts span{font-size:11px;color:#8a97ab}.validation-tabs{display:flex;gap:24px;padding:0 24px;border-bottom:1px solid #e5eaf2;flex-shrink:0}.validation-tabs button{display:flex;align-items:center;gap:6px;padding:10px 0 12px;border:0;border-bottom:2px solid transparent;background:none;font-size:12px;color:#8391a7;cursor:pointer}.validation-tabs button.active{color:#2563eb;border-bottom-color:#2563eb}.validation-tabs b{font-size:10px;font-weight:400;color:#94a3b8}.validation-tabs i{width:5px;height:5px;border-radius:50%;background:#d3a957}.validation-body{overflow:auto;min-height:0;flex:1;padding:16px 24px 24px;background:#fbfcfe}.validation-intro{font-size:11px;color:#8a98ac;margin:0 0 14px;line-height:1.8}.validation-table-wrap{overflow:auto;border:1px solid #e4eaf2;border-radius:7px;background:white}.validation-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;text-align:left}.validation-table th{padding:11px 13px;background:#f4f7fb;font-size:11px;font-weight:500;color:#8493a9;border-bottom:1px solid #e5eaf2}.validation-table th:nth-child(1){width:17%}.validation-table th:nth-child(2){width:34%}.validation-table th:nth-child(3){width:37%}.validation-table th:nth-child(4){width:12%}.validation-table td{vertical-align:top;padding:14px 13px;border-bottom:1px solid #e9eef5;overflow-wrap:anywhere;white-space:pre-wrap;line-height:1.8;color:#4c5e79}.validation-table tr:last-child td{border:0}.validation-table td>strong{font-weight:500;color:#42536d}.validation-table td p{margin:6px 0 0;font-size:11px;color:#91a0b4;line-height:1.8}.validation-table td .validation-unchanged{color:#b08c4f}.validation-value-empty{color:#a2adbd}.validation-badge{display:inline-block;font-size:10px;border-radius:4px;padding:1px 6px;background:#eef5f1;color:#57866a}.validation-badge.manual{background:#fff5df;color:#aa8744}.validation-badge.issue{background:#fff0ed;color:#b47669}.validation-badge.not_checked{background:#eef1f7;color:#8b99ae}.validation-locate{border:0;background:none;color:#4e78d0;font-size:11px;display:flex;align-items:center;gap:5px;white-space:nowrap;padding:0;cursor:pointer}.validation-locate svg{width:12px;height:12px}.validation-empty{display:flex;align-items:center;justify-content:center;flex-direction:column;min-height:190px;color:#8a9bb2;gap:10px}.validation-empty>svg{color:#70a58a;width:28px;height:28px}.validation-empty strong{font-size:14px;font-weight:500;color:#64748b}.validation-empty p{font-size:12px;margin:0}.validation-difference{padding:15px;margin-bottom:14px;background:white;border:1px solid #e3e9f2;border-radius:8px}.validation-difference h4{font-size:12px;font-weight:500;margin:0 0 12px;color:#63738c}.validation-difference>div{display:grid;grid-template-columns:1fr 1fr;gap:14px}.validation-difference section{padding:12px;border-radius:5px;background:#f6f8fc;min-width:0}.validation-difference section:last-child{background:#fff7f4}.validation-difference section>span{font-size:10px;color:#98a4b5}.validation-difference p{font-size:12px;color:#5f718d;line-height:1.9;margin:7px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}.validation-scope h4{font-size:13px;color:#52637b;margin:7px 0 10px;font-weight:600}.validation-scope p,.validation-scope li{font-size:12px;line-height:1.9;color:#8a99ad}.validation-scope ul{padding-left:18px;list-style:disc}.validation-scope h4:not(:first-child){margin-top:24px}.validation-scope-note{font-size:11px;line-height:1.8;padding:13px 15px;background:#eef3fc;color:#7f95b9;border-radius:6px;margin-top:18px}.validation-footer{display:flex;align-items:center;justify-content:space-between;padding:13px 24px;background:white;border-top:1px solid #e5eaf2;flex-shrink:0}.validation-footer>span{font-size:11px;color:#a0abbb}.validation-footer .button{font-size:12px;padding:8px 15px}@media(max-width:700px){.validation-overlay{padding:10px}.validation-dialog{width:100%;height:94vh}.validation-header{padding:16px}.validation-header p span{display:none}.validation-summary{margin:12px 14px}.validation-counts{margin:0 14px 10px;padding:10px 0}.validation-counts>div{flex-direction:column;gap:3px;align-items:center}.validation-counts strong{font-size:19px}.validation-counts span{font-size:9px;text-align:center}.validation-tabs{padding:0 14px;gap:15px;overflow:auto}.validation-tabs button{white-space:nowrap;font-size:11px}.validation-body{padding:14px}.validation-table{min-width:700px}.validation-footer{padding:12px 14px}.validation-footer>span{display:none}.validation-footer .button{margin-left:auto}.validation-difference>div{grid-template-columns:1fr}}
</style>
